      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "Sem as precedências, não se sabe se a redução de duração altera o término final ou qual seria sua magnitude."
    ],
    "motivo": "A alteração reduz a duração de uma atividade, mas não basta para quantificar a variação do marco final sem as relações de precedência.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa declara orçamento de R$ 5.000,00.",
