  },
  "custo_novo": {
    "estado": "exato",
    "valor": 490000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "O crédito definitivo reduz o custo em R$ 100,00. A única cobrança variável é por extensão além de D10; a alteração reduz uma duração e mantém as demais condições, não gerando extensão sobre a linha base.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": -10000,
    "direcao": "reducao",
    "evidencias": [
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      }
    ],
    "lacunas": [],
    "motivo": "Crédito de R$ 100,00 sobre a linha base; não há cobrança de extensão além de D10.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A duração do preparo cai de cinco para quatro dias, mas as precedências ausentes impedem estimar a data final nova e sua variação. O crédito definitivo de R$ 100,00 é explícito; com as demais condições mantidas e sem extensão além da linha base, a redução líquida do custo é de 10.000 centavos."
}

